insert into storage.buckets(id,name,public) values ('product-images','product-images',true),('category-images','category-images',true),('brand-assets','brand-assets',true),('homepage-media','homepage-media',true) on conflict(id) do nothing;
create policy "public media read" on storage.objects for select using(bucket_id in ('product-images','category-images','brand-assets','homepage-media')); create policy "admins upload media" on storage.objects for insert to authenticated with check(bucket_id in ('product-images','category-images','brand-assets','homepage-media') and public.is_admin()); create policy "admins update media" on storage.objects for update to authenticated using(public.is_admin()) with check(public.is_admin()); create policy "admins delete media" on storage.objects for delete to authenticated using(public.is_admin());
